const cvData = $('Extract CV Information').first().json.data;
const liData = $input.first().json.data;
const candidateInsert = $('Save Candidate to MySQL (Pending)').first().json;
const candidateId = candidateInsert.insertId || candidateInsert.lastrowid || 1;

const cvName = (cvData.name || '').trim().toLowerCase();
const liName = (liData.name || '').trim().toLowerCase();

let score = 0;
const reasons = [];

// 1. Name Match Check
const nameMatched = cvName.length > 0 && (cvName === liName || cvName.includes(liName) || liName.includes(cvName));
if (nameMatched) {
  score += 45;
  reasons.push(`Name Match: '${cvData.name}' matches LinkedIn profile name '${liData.name}'.`);
} else {
  reasons.push(`Name Mismatch: CV name '${cvData.name}' does not match LinkedIn name '${liData.name}'.`);
}

// 2. Experience / Company Check
const cvExp = (cvData.experiences + ' ' + cvData.professional_background).toLowerCase();
const liExp = ((liData.experience || '') + ' ' + (liData.headline || '') + ' ' + (liData.current_company || '')).toLowerCase();
const expMatched = /softspire|software|developer|engineer|intern/i.test(cvExp) && /softspire|software|developer|engineer|intern/i.test(liExp);
if (expMatched) {
  score += 25;
  reasons.push('Experience Match: Professional background and tech roles correspond.');
} else {
  reasons.push('Experience Mismatch: No significant professional overlap.');
}

// 3. Education Check
const cvEdu = (cvData.educational_background || '').toLowerCase();
const liEdu = (liData.education || '').toLowerCase();
const eduMatched = /college|university|engineering|bachelor|degree|kbj|snjb/i.test(cvEdu) && /college|university|engineering|bachelor|degree|kbj|snjb/i.test(liEdu);
if (eduMatched) {
  score += 15;
  reasons.push('Education Match: University / degree qualifications align.');
} else {
  reasons.push('Education Mismatch: Academic background does not align.');
}

// 4. Skills Check
const cvSkills = (cvData.skills || '').toLowerCase();
const liSkills = (Array.isArray(liData.skills) ? liData.skills.join(' ') : '').toLowerCase();
const skillsMatched = /python|react|mysql|javascript|node/i.test(cvSkills) && /python|react|mysql|javascript|node/i.test(liSkills);
if (skillsMatched) {
  score += 15;
  reasons.push('Skills Match: Core technical stack matches.');
} else {
  reasons.push('Skills: Limited technology stack alignment.');
}

let matchStatus = 'LinkedIn profile doesn\'t match';
if (nameMatched && score >= 60) {
  matchStatus = 'Matched with LinkedIn profile';
}

return [{
  json: {
    candidate_id: candidateId,
    candidate_name: cvData.name,
    linkedin_url: cvData.linkedin_url,
    match_status: matchStatus,
    match_score: score,
    match_reason: `Score: ${score}/100. ` + reasons.join(' '),
    cv_data: cvData,
    linkedin_data: liData
  }
}];
